<template>
  <div class="login-page">
    <b-card class="login-card" shadow="never">
      <div class="text-center mb-4">
        <b-icon icon="shield-lock" font-scale="2.6" variant="primary" />
        <h3 class="mt-3 mb-1">Đăng nhập</h3>
        <p class="text-muted mb-0">Đăng nhập để sử dụng hệ thống</p>
        <b-badge variant="warning" class="mt-2">DEMO - không xác thực thật</b-badge>
      </div>

      <b-form @submit.prevent="onSubmit">
        <b-form-group label="Tên đăng nhập" label-for="login-username"
                      label-cols="4" label-cols-sm="4" label-align-sm="right" class="mb-3">
          <b-form-input id="login-username" v-model.trim="username"
                        autocomplete="username" required placeholder="Nhập tên đăng nhập" />
        </b-form-group>
        <b-form-group label="Mật khẩu" label-for="login-password"
                      label-cols="4" label-cols-sm="4" label-align-sm="right" class="mb-3">
          <b-input-group>
            <b-form-input id="login-password" v-model="password"
                          :type="showPassword ? 'text' : 'password'"
                          autocomplete="current-password" required placeholder="Nhập mật khẩu" />
            <b-input-group-append>
              <b-button variant="outline-secondary" type="button"
                        :aria-label="showPassword ? 'Ẩn mật khẩu' : 'Hiện mật khẩu'"
                        @click="showPassword = !showPassword">
                <b-icon :icon="showPassword ? 'eye-slash' : 'eye'" />
              </b-button>
            </b-input-group-append>
          </b-input-group>
        </b-form-group>
        <b-alert :show="!!message" variant="danger">{{ message }}</b-alert>
        <b-button type="submit" block variant="primary" class="mt-4">Đăng nhập</b-button>
      </b-form>
      <div class="text-center mt-3">
        <small class="text-muted d-block mb-2">Tài khoản thử: admin, thuc hoặc tri / Mật khẩu: demo123</small>
        <router-link to="/">Về trang chủ</router-link>
      </div>
    </b-card>
  </div>
</template>

<script>
import { loginMock } from '@/config/mockAuth'

export default {
  name: 'Login',
  data() {
    return { username: '', password: '', showPassword: false, message: '' }
  },
  methods: {
    onSubmit() {
      this.message = ''
      const result = loginMock(this.username, this.password)
      if (!result.ok) {
        this.message = result.message
        return
      }
      // DEMO: chỉ lưu thông tin hiển thị, tuyệt đối không lưu mật khẩu.
      // Không dùng dữ liệu này để cho phép truy cập API hoặc phân quyền thật.
      sessionStorage.setItem('mockUser', JSON.stringify(result.user))
      this.$root.$emit('mock-auth-changed')
      this.password = ''
      const redirect = this.$route.query.redirect
      const destination = typeof redirect === 'string' && redirect.startsWith('/') && !redirect.startsWith('//')
        ? redirect
        : '/'
      this.$router.push(destination)
    }
  }
}
</script>

