// Khi có API .NET 8, đặt enabled=false và thay loginMock bằng API.
export const mockAuthConfig = {
  enabled: true,
  accounts: [
    { id: 5, username: 'admin', password: 'demo123', fullName: 'Admin', email: 'thuc101@gmail.com', accessLevel: 9, isActive: true },
    { id: 6, username: 'thuc', password: 'demo123', fullName: 'thuc', email: 'tucthan.4@gmail.com', accessLevel: 1, isActive: true },
    { id: 7, username: 'tri', password: 'demo123', fullName: 'Nguyễn Tấn Trí', email: 'tri@gmail.com', accessLevel: 1, isActive: true }
  ]
}

export function loginMock(username, password) {
  if (!mockAuthConfig.enabled) {
    return { ok: false, message: 'Chưa cấu hình API đăng nhập.' }
  }
  const account = mockAuthConfig.accounts.find(u => u.username.toLowerCase() === String(username).trim().toLowerCase())
  if (!account || account.password !== password) {
    return { ok: false, message: 'Tên đăng nhập hoặc mật khẩu không đúng.' }
  }
  if (!account.isActive) {
    return { ok: false, message: 'Tài khoản đã bị khóa.' }
  }
  const { password: ignored, ...profile } = account
  return { ok: true, user: profile }
}
